function outer() {
  const message = "Hello";

  function inner() {
    console.log(message);
  }

  inner();
}

outer(); // "Hello"

function outer() {
  const value = "outer value";

  function inner() {
    const value = "inner value"; // this hides (shadows) the outer "value"
    console.log(value);
  }

  inner();
  console.log(value);
}

outer();
// "inner value"
// "outer value"

const appName = "MyApp";

function greet() {
  console.log(`Welcome to ${appName}`);
}

greet(); // "Welcome to MyApp"

console.log(score); // undefined (var is hoisted, but not its value)
var score = 10;

sayHi(); // "Hi!" (function declarations are hoisted completely)
function sayHi() {
  console.log("Hi!");
}

if (true) {
  let blockScoped = "only inside this block";
  var notBlockScoped = "leaks outside the block";
}

console.log(notBlockScoped); // "leaks outside the block"
console.log(typeof blockScoped); // "undefined" (blockScoped does not exist here)

const funcsWithVar = [];
for (var i = 0; i < 3; i++) {
  funcsWithVar.push(function () {
    return i;
  });
}
console.log(funcsWithVar.map((f) => f())); // [3, 3, 3]

const funcsWithLet = [];
for (let j = 0; j < 3; j++) {
  funcsWithLet.push(function () {
    return j;
  });
}
console.log(funcsWithLet.map((f) => f())); // [0, 1, 2]

