assignment.solution:
const funcs = [];
for (let i = 0; i < 3; i++) {
  funcs.push(function () {
    return i;
  });
}
console.log(funcs.map((f) => f())); // [0, 1, 2]

// var is scoped to the whole function, so all three functions shared
// the same "i", which was 3 after the loop finished.
// let creates a brand new "i" for every loop iteration, so each
// function keeps (closes over) its own separate value.
